"""Name and image tables generated by tools/build_data.py (sources listed there and in FINDINGS.md)."""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

DATA_DIR = Path(__file__).resolve().parent / "data"


@lru_cache(maxsize=None)
def game_data() -> dict:
    return json.loads((DATA_DIR / "game_data.json").read_text(encoding="utf-8"))


@lru_cache(maxsize=None)
def images() -> dict:
    try:
        return json.loads((DATA_DIR / "images.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {"steam": {}, "campaigns": {}, "characters": {}}


@dataclass(frozen=True)
class MapInfo:
    map: str
    campaign: int | None  # 1..14, None for a custom map
    chapter: int | None  # 1-based
    chapters: int | None

    @property
    def finale(self) -> bool:
        return bool(self.chapter and self.chapters and self.chapter == self.chapters)


def map_info(map_name: str | None) -> MapInfo | None:
    if not map_name:
        return None
    name = map_name.lower().removesuffix(".bsp")
    entry = game_data()["maps"].get(name)
    if entry is None:
        return MapInfo(name, None, None, None)
    return MapInfo(name, entry["campaign"], entry.get("chapter"), entry.get("chapters"))


def next_map(map_name: str | None) -> str | None:
    """The chapter after this one in the same campaign, or None (finale, custom map)."""
    info = map_info(map_name)
    if not info or not info.campaign or not info.chapter or info.finale:
        return None
    for c in game_data()["campaigns"]:
        if c["id"] == info.campaign and info.chapter < len(c["chapters"]):
            return c["chapters"][info.chapter]["map"].lower()
    return None


def campaign_name(campaign: int | None, lang: str) -> str | None:
    if not campaign:
        return None
    for c in game_data()["campaigns"]:
        if c["id"] == campaign:
            return c["names"].get(lang) or c["names"].get("en")
    return None


def chapter_name(map_name: str | None, lang: str) -> str | None:
    info = map_info(map_name)
    if not info or not info.campaign:
        return None
    for c in game_data()["campaigns"]:
        if c["id"] == info.campaign:
            for ch in c["chapters"]:
                if ch["map"].lower() == info.map:
                    return ch["names"].get(lang) or ch["names"].get("en")
    entry = game_data()["maps"].get(info.map, {})
    names = entry.get("names") or {}
    return names.get(lang) or names.get("en")


def difficulty_name(value: str | None, lang: str) -> str | None:
    if not value:
        return None
    for key, names in game_data()["difficulties"].items():
        if key.lower() == value.lower():
            return names.get(lang) or names.get("en")
    return None


def weapon(cls: str | None) -> dict | None:
    if not cls:
        return None
    return game_data()["weapons"].get(cls)


def weapon_name(cls: str | None, lang: str) -> str | None:
    w = weapon(cls)
    if not w:
        return None
    return w["names"].get(lang) or w["names"].get("en")


def survivors() -> list[str]:
    return list(game_data()["survivors"])


def special_infected() -> list[str]:
    return list(game_data()["special_infected"])


def campaign_image(campaign: int | None) -> str | None:
    if not campaign:
        return None
    return images()["campaigns"].get(str(campaign))


def character_image(name: str | None) -> str | None:
    if not name:
        return None
    return images()["characters"].get(name)


def cover_image() -> str | None:
    return images()["steam"].get("cover") or images()["steam"].get("header")
